/**
 * A real native recording whose execution trees are long `next` chains: a
 * root loop and one sub-flow mount (a `children` entry of the root's first
 * stage) whose own loop runs as long. Generated by running footprintjs at
 * test time (no stored file), then passed through JSON text as a host would
 * store and send it.
 *
 * The root loop's stage carries the declared tag `tick`.
 *
 * `stages` is the length of BOTH chains (root `executionTree` and the child's
 * `treeContext.stageContexts`), counted along `next` from the tree's root.
 */
import { flowChart, FlowChartExecutor } from 'footprintjs';

type Json = Record<string, any>;

/** The loop count that makes a chain of `stages` stages (a seed stage plus the loop's visits). */
const visitsFor = (stages: number) => stages - 1;

export async function stageChainRecording(stages: number): Promise<Json> {
  const visits = visitsFor(stages);
  const loop = (name: string) => flowChart<{ count: number }>(name, scope => { scope.count = 0; }, `${name}-seed`)
    .addFunction('Tick', scope => { scope.count += 1; if (scope.count >= visits) scope.$break(); }, `${name}-tick`)
    .loopTo(`${name}-tick`);
  const chart = flowChart<{ count: number }>('Root', scope => { scope.count = 0; }, 'root-seed')
    .addSubFlowChart('sf-child', loop('child').build())
    .addFunction('Tick', scope => { scope.count += 1; if (scope.count >= visits) scope.$break(); }, 'root-tick')
    .tag('tick')
    .loopTo('root-tick')
    .build();
  const executor = new FlowChartExecutor(chart);
  // The engine's loop guard defaults to 1,000 visits; a longer fixture raises it.
  await executor.run({ maxIterations: stages + 1 });
  const recording = JSON.parse(JSON.stringify({ snapshot: executor.getSnapshot(), events: [], structure: chart.buildTimeStructure }));
  const root = chainLength(recording.snapshot.executionTree);
  const child = chainLength(recording.snapshot.subflowResults['sf-child#1'].treeContext.stageContexts);
  if (root !== stages || child !== stages) throw new Error(`Expected ${stages}-stage chains, built ${root} and ${child}.`);
  return recording;
}

/** Stages along `next` from a tree's root, counted with a loop. */
export function chainLength(tree: unknown): number {
  let count = 0;
  for (let stage = tree as Json | undefined; stage; stage = stage.next) count++;
  return count;
}

/** The last stage of a chain, reached with a loop. */
export function lastStage(tree: unknown): Json {
  let stage = tree as Json;
  while (stage.next) stage = stage.next;
  return stage;
}

/** A plain object nested `levels` deep along the given key, built with a loop. */
export function nested(levels: number, key = 'next', leaf: unknown = 'leaf'): Json {
  let value: unknown = leaf;
  for (let i = 0; i < levels; i++) value = { [key]: value };
  return value as Json;
}
